__NUXT_JSONP__("/th/programs", (function(a,b){return {data:[{details:{slug:"th",pageTitle:"โปรแกรม | Mentor Language Institute",pageDescription:"รายละเอียด 8 หลักสูตรของ MLI: หลักสูตรภาษาอังกฤษทั่วไป, TOEFL®, IELTS™, หลักสูตรสนทนาภาษาอังกฤษ, หลักสูตรภาษาอังกฤษเพื่อธุรกิจ + TOEIC®, GRE® \u002F GMAT®",title:"โปรแกรม",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fmli_course.jpg",programs:{title:"รายละเอียด 7 หลักสูตรของ MLI",lists:["ESL โปรแกรม","Vacation ESL โปรแกรม",a,"IELTS โปรแกรม","Conversation Intermediate โปรแกรม","Conversation Advanced โปรแกรม",b]},subtitle:["เป็นหลักสูตรภาษาอังกฤษทั้งหมด \u003Cbr \u002F\u003Eนักเรียนส่วนใหญ่จะเริ่มต้นด้วยหลักสูตร ESL หลังจากนั้นมักจะเรียนพิเศษเพิ่มเติม เช่นTOEFL®.\u003Cbr \u002F\u003E※บางชั้นเรียนต้องผ่านการทดสอบ จึงจะสามารถเข้าร่วมได้"],services_esl:[{title:"ESL โปรแกรม (ภาษาอังกฤษทั่วไป)",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fesl.png",subtitle:"หลักสูตรนี้จะเน้นการสื่อสารภาษาอังกฤษที่เป็นประโยชน์ทั้ง 4 ทักษะ (การเขียน การฟัง การพูดและการอ่าน)",description:["ESL เป็นหลักสูตรยอดนิยมของ MLI\u003Cbr \u002F\u003Eเนื่องจากหลักสูตรนี้แบ่งออกเป็น 8 ระดับ \u003Cbr \u002F\u003Eจึงทำให้ท่านสามารถพัฒนาทักษะภาษาอังกฤษในชั้นเรียนที่ตรงกับความสามารถของท่านอย่างเต็มที่"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FAq_MfkF3x0g"}],services_toefl:[{title:a,image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Ftoefl.png",link:"https:\u002F\u002Fmliesl.edu\u002Fcontents\u002Fth\u002Ftoefl-ibt-รูปแบบใหม่ปี-2026สรุปการเ\u002F",other_image:"\u002Fimages\u002Fcourses\u002Fcourse\u002FBanner_TOEFL_Jan_21.png",subtitle:"TOEFL® iBT เป็นแบบทดสอบเพื่อประเมินความสามารถทางภาษาอังกฤษของผู้ที่ไม่ได้ใช้ภาษาอังกฤษเป็นภาษาหลัก คะแนนการสอบ TOEFL® จึงจำเป็นสำหรับมหาวิทยาลัยหลายแห่งในสหรัฐอเมริกา รวมถึงหน่วยงานของรัฐ องค์กรเอกชน องค์กรที่ได้รับการรับรองมาตรฐานและสถาบันการศึกษา",description:["หลักสูตร TOEFL® ของ MLI มุ่งเน้นไปที่การทดสอบและพัฒนาทักษะทั้ง 4 ด้าน (การเขียน การฟัง การพูดและการอ่าน) เพื่อให้ได้คะแนนสูงสุด ในการทดสอบบนอินเทอร์เน็ต (iBT)"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FKYPYbU-D3M0"}],services_ielts:[{title:"IELTS™️ โปรแกรม",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fielts.jpg",subtitle:"IELTS ™เป็นการทดสอบที่พัฒนาขึ้นในสหราชอาณาจักรและออสเตรเลียเพื่อประเมินความสามารถทางภาษาอังกฤษของนักเรียน เมื่อเร็ว ๆ นี้มหาวิทยาลัยในอเมริกาจำนวนมากต้องการคะแนนTOEFL®หรือคะแนน IELTS ™",description:["หลักสูตรนี้จะช่วยพัฒนาทักษะทั้ง 4 ด้าน คือ การฟัง การพูด การอ่านและการเขียน ผู้เรียนจะสามารถเรียนรู้ทักษะและกลยุทธ์เพื่อพิชิตคะแนนสอบในแต่ละส่วน \u003Cbr \u002F\u003E กล่าวได้ว่า IELTS ™ นั้นค่อนข้างง่ายกว่าTOEFL® \u003Cbr \u002F\u003Eเพราะเป็นหลักสูตรที่สมบูรณ์ สำหรับนักเรียนที่พบว่า TOEFL® นั้นยาก"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002Fho7kUVZoOng"}],services_conversation:[{title:"โปรแกรมสนทนา",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fconversation.png",subtitle:"หลักสูตรนี้มุ่งเน้นไปที่บทสนทนาในชีวิตประจำวันและมีวัตถุประสงค์เพื่อช่วยให้ผู้เรียนพูดภาษาอังกฤษได้อย่างคล่องแคล่ว",description:["โปรแกรมของเราเน้นการเพิ่มทักษะการสนทนาภาษาอังกฤษของคุณผ่านกิจกรรมที่น่าสนใจและการเรียนรู้แบบแอ็กทิว! ในคลาสสนทนาของเรา นักเรียนจะได้สำรวจกำแพงคำศัพท์ วลี และสำนวนที่จะทำให้บทสนทนาของคุณมีชีวิตชีวาขึ้นมา ฝึกพูดออกเสียงในคลาส CMAR ผ่านการสนทนาสนุกๆ การเล่นบทบาท และกิจกรรมกลุ่ม คุณจะได้ความมั่นใจในการแสดงออกและการเข้าร่วมสนทนาที่มีความหมาย ผู้สอนที่มีประสบการณ์จะให้สนับสนุนในสภาพแวดล้อมการเรียนรู้และแนะนำคุณในการค้นพบภาษา"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002Fmg04cOOxTQ4"}],services_toeic:[{title:b,image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fbusiness-toeic.png",subtitle:"ในธุรกิจต่างประเทศ ภาษาอังกฤษเป็นภาษาสากลของโลก จุดมุ่งหมายของหลักสูตรนี้คือการพัฒนาทักษะการสื่อสารทางธุรกิจเป็นภาษาอังกฤษ",description:["ทักษะภาษาอังกฤษของท่านจะถูกพัฒนาให้ดียิ่งขึ้น ด้วยการจำลองเชิงปฏิบัติ เช่น การนำเสนอ Power Point การรับโทรศัพท์ การเจรจาและการประชุม แต่ยังคงเน้นคำศัพท์ การฟัง การเขียนและการพูดคุยด้านธุรกิจ"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F2htjAgPz984",other_info:{description:["การทดสอบ TOEIC®เป็นตัวบ่งชี้ความสามารถทางภาษาอังกฤษในธุรกิจและถูกใช้โดยบริษัท และองค์กรต่างๆทั่วโลก หลักสูตรธุรกิจและ หลักสูตรTOEIC® จะเตรียมความพร้อมให้ผู้เรียนประสบความสำเร็จในการสอบ TOEIC® โดยการสอบการฟังและการเขียน โดยการแนะนำคำศัพท์ที่จำเป็นและสำรวจกลยุทธ์ต่างๆ เพื่อให้ได้คะแนนสูงในการทดสอบ","หลักสูตรนี้จะเป็นประโยชน์ในการพัฒนาทักษะภาษาอังกฤษของท่าน เช่น คำศัพท์ การอ่าน การฟังและไวยากรณ์ โดยการเรียนรู้กลยุทธ์ในการหาคำตอบที่ถูกต้อง และท่านจะสามารถพิชิตคะแนนสูงสุดมาได้"]}}],services_private:[{title:"Private Lessons",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fprivate-lessons.png",subtitle:"บทเรียนส่วนตัวได้รับการปรับแต่งให้ตรงตามวัตถุประสงค์ของคุณในการตั้งค่าแบบตัวต่อตัวหรือแบบกลุ่มย่อย",description:["บทเรียนส่วนตัวเป็นตัวเลือกการเรียนรู้ภาษาที่ยืดหยุ่นที่สุดของเรา ผู้สอนที่ผ่านการฝึกอบรมมาอย่างดีจะพัฒนาบทเรียนส่วนบุคคลที่ออกแบบมาเพื่อช่วยให้คุณบรรลุเป้าหมายภาษาอังกฤษที่เฉพาะเจาะจง คุณสามารถเรียนอะไรก็ได้ตั้งแต่ทักษะภาษาอังกฤษทั่วไป, การสนทนา, ความคล่องแคล่ว, การลดสำเนียง, ภาษาอังกฤษธุรกิจ, TOEFL, TOEIC, GRE และอื่นๆ คุณสามารถกำหนดเวลาเรียนแบบตัวต่อตัวได้ตามความพร้อมให้บริการและความเร็วที่ต้องการ ตัวอย่างเช่น หากคุณต้องการเรียนแบบเข้มข้น คุณอาจขอเรียนแบบตัวต่อตัวทุกวันเป็นเวลา 3 ชั่วโมง หรือหากคุณต้องการก้าวที่ผ่อนคลายมากขึ้น คุณอาจขอเรียนแบบตัวต่อตัวเพียงสัปดาห์ละครั้งเป็นเวลา 1 ชั่วโมง คุณจะได้รับความยืดหยุ่น คำแนะนำส่วนบุคคล และความเร็วที่เหมาะกับคุณในราคาที่เหมาะสม! ","ค่าใช้จ่ายบทเรียนส่วนตัวปกติ: \u003Cbr \u002F\u003E$80\u002F1 ชั่วโมง \u003Cbr \u002F\u003E$912\u002F12 ชั่วโมง \u003Cbr \u002F\u003E$1,632\u002F24 ชั่วโมง \u003Cbr \u002F\u003E$2,688\u002F48 ชั่วโมง","หากนักเรียนร้องขอครูคนใดคนหนึ่ง:  \u003Cbr \u002F\u003E $92\u002F1 ชั่วโมง \u003Cbr \u002F\u003E $1,044\u002F12 ชั่วโมง \u003Cbr \u002F\u003E $1,896\u002F24 ชั่วโมง \u003Cbr \u002F\u003E $3,120\u002F48 ชั่วโมง","*ถ้านักเรียน 2 คนแชร์บทเรียนแบบตัวต่อตัว นักเรียนคนที่สองลด 50%."]}],dir:"\u002Fprograms",path:"\u002Fprograms\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.555Z",updatedAt:"2026-04-30T16:49:50.518Z"}}],fetch:{},mutations:void 0}}("โปรแกรม TOEFL® Test Preparation \u002F TOEFL® and University Preparation","Business plus TOEIC โปรแกรม")));